const items = $input.all();
const agora = $now.setZone('America/Sao_Paulo').toFormat('HH:mm');

return items.map(item => {
  const u = item.json;

  // Tratamento do nome: Primeira maiúscula, restante minúscula
  const rawName = u.frist_name || '';
  const nome = rawName.charAt(0).toUpperCase() + rawName.slice(1).toLowerCase();

  const gender = (u.gender || 'masculino').toLowerCase();
  const suf = gender === 'feminino' ? 'a' : 'o';

  const tarefasProcessadas = u.tasks.map((t, i) => {
    const scheduledType = t.scheduled_type || 'hora';
    const tipo = t.tipo_envio;
    const id_visual = i + 1;

    let horarioDisplay = '';
    if (scheduledType === 'hora') {
      horarioDisplay = t.scheduled_time ? t.scheduled_time.substring(0, 5) : 'não definido';
    } else if (scheduledType === 'dia') {
      horarioDisplay = 'hoje';
    } else if (scheduledType === 'turno') {
      const hora = t.scheduled_time ? parseInt(t.scheduled_time.substring(0, 2), 10) : null;
      if (hora !== null) {
        if (hora >= 3 && hora < 12) horarioDisplay = 'manhã';
        else if (hora >= 12 && hora < 18) horarioDisplay = 'tarde';
        else horarioDisplay = 'noite';
      } else {
        horarioDisplay = 'turno não definido';
      }
    }

    let tipoDisparo = '';
    if (tipo === 'lembrete_antecipado') tipoDisparo = 'lembrete_antecipado';
    else if (tipo === 'lembrete') tipoDisparo = 'hora_marcada';
    else tipoDisparo = 'confirmacao';

    return {
      id: t.id,
      id_visual,
      title: t.title,
      category: t.category || 'geral',
      horario: horarioDisplay,
      scheduled_type: scheduledType,
      tipo_disparo: tipoDisparo,
      reminder_minutes: t.reminder_minutes_before || null
    };
  });

  const linhasTarefas = tarefasProcessadas.map(t => {
    let linha = `TAREFA ${t.id_visual}:\n`;
    linha += `  Título: ${t.title}\n`;
    linha += `  Horário: ${t.horario} (${t.scheduled_type})\n`;
    linha += `  Tipo de disparo: ${t.tipo_disparo}`;
    if (t.reminder_minutes) linha += `\n  Antecedência: ${t.reminder_minutes} minutos`;
    return linha;
  }).join('\n\n');

const userPrompt =
    `Gere UMA mensagem única no WhatsApp.\n\n` +
    `Hora atual: ${agora}\n\n` +
    `Retorne SOMENTE o nome da tarefa e o horário, separados por vírgula. Sem texto adicional, sem saudação, sem emoji, sem explicação, sem numeração.\n\n` +
    `Formato: nome da tarefa, horário\n` +
    `Se houver múltiplas tarefas, uma por linha:\n` +
    `nome da tarefa, horário\n` +
    `nome da tarefa, horário\n\n` +
    `${linhasTarefas}`;

  return {
    json: {
      user_phone: u.user_phone,
      frist_name: nome, // Agora retorna o nome formatado
      gender: gender,
      task_ids: tarefasProcessadas.map(t => t.id),
      tarefas: tarefasProcessadas,
      user_prompt: userPrompt
    }
  };
});

const items = $input.all();

// Agrupa todas as tarefas por user_phone
const grouped = {};

for (const item of items) {
  const t = item.json;
  const phone = t.user_phone;

  if (!grouped[phone]) {
    grouped[phone] = {
      user_phone: phone,
      frist_name: t.frist_name,
      gender: t.gender,
      // Adicionando os campos de metadados do usuário aqui
      created_from: t.created_from,
      last_interaction_at: t.last_interaction_at,
      tasks: []
    };
  }

  // Se você quiser garantir que esses campos de meta sejam sempre atualizados 
  // com a última interação processada, você pode adicionar isso aqui:
  grouped[phone].last_interaction_at = t.last_interaction_at;

  grouped[phone].tasks.push({
    id:                       t.id,
    title:                    t.title,
    category:                 t.category,
    scheduled_time:           t.scheduled_time,
    scheduled_type:           t.scheduled_type || 'hora',
    reminder_minutes_before:  t.reminder_minutes_before,
    tipo_envio:               t.tipo_envio
  });
}

return Object.values(grouped).map(u => ({ json: u }));

